// HeroRecord is a shared struct (catalogue type).
// A hero progression record (0x98 bytes, copied field for field by FUN_7ff650f9b9e0): level, hero GUID
// 0x02E..., xp (+0x10, VM 0x4ACDC2D3), xp to next (+0x18) [?], equipped skin +0x20, equipped unlocks
// +0x28..+0x60 (SkinTheme, HeroMod 0-2, POTG intro, spray, class 0x5F38A9D5, trophy), per-skin themes
// {ctx = skin, theme}, owned hero unlocks. docs/TitleScreen.md §5.
type HeroRecord struct {
	F0             uint8
	Level          uint32
	Hero           uint64
	Xp             uint64
	XpNext         uint64
	Skin           uint64
	SkinTheme      uint64
	HeroMod0       uint64
	HeroMod1       uint64
	HeroMod2       uint64
	Potg           uint64
	Spray          uint64
	Unlock5F38A9D5 uint64
	Trophy         uint64
	Themes         []HeroRecordThemes
	Owned          []Unlock
}

func (m *HeroRecord) encode(w *bits.Writer) {
	putU8(w, m.F0)
	putU32(w, m.Level)
	putU64(w, m.Hero)
	putU64(w, m.Xp)
	putU64(w, m.XpNext)
	putU64(w, m.Skin)
	putU64(w, m.SkinTheme)
	putU64(w, m.HeroMod0)
	putU64(w, m.HeroMod1)
	putU64(w, m.HeroMod2)
	putU64(w, m.Potg)
	putU64(w, m.Spray)
	putU64(w, m.Unlock5F38A9D5)
	putU64(w, m.Trophy)
	putCount(w, len(m.Themes))
	for i1 := range m.Themes {
		m.Themes[i1].encode(w)
	}
	putCount(w, len(m.Owned))
	for i1 := range m.Owned {
		m.Owned[i1].encode(w)
	}
}

func (m *HeroRecord) decode(d *decoder) {
	m.F0 = d.getU8()
	m.Level = d.getU32()
	m.Hero = d.getU64()
	m.Xp = d.getU64()
	m.XpNext = d.getU64()
	m.Skin = d.getU64()
	m.SkinTheme = d.getU64()
	m.HeroMod0 = d.getU64()
	m.HeroMod1 = d.getU64()
	m.HeroMod2 = d.getU64()
	m.Potg = d.getU64()
	m.Spray = d.getU64()
	m.Unlock5F38A9D5 = d.getU64()
	m.Trophy = d.getU64()
	m.Themes = make([]HeroRecordThemes, d.count(128))
	for i1 := range m.Themes {
		m.Themes[i1].decode(d)
	}
	m.Owned = make([]Unlock, d.count(161))
	for i1 := range m.Owned {
		m.Owned[i1].decode(d)
	}
}

