// tickets = searching, 1->0 = stopped (docs/LobbyServer.md "Matchmaking").
type QueueStatus struct {
	Status   uint32
	F1       int32
	Stats    []QueueStats
	Ticket   MatchmakingTicket
	Tickets1 []MatchmakingTicket
	Tickets2 []MatchmakingTicket
	Entries  []QueueEntry
}

func (m *QueueStatus) encode(w *bits.Writer) {
	putU32(w, m.Status)
	putI32(w, m.F1)
	putCount(w, len(m.Stats))
	for i1 := range m.Stats {
		m.Stats[i1].encode(w)
	}
	m.Ticket.encode(w)
	putCount(w, len(m.Tickets1))
	for i1 := range m.Tickets1 {
		m.Tickets1[i1].encode(w)
	}
	putCount(w, len(m.Tickets2))
	for i1 := range m.Tickets2 {
		m.Tickets2[i1].encode(w)
	}
	putCount(w, len(m.Entries))
	for i1 := range m.Entries {
		m.Entries[i1].encode(w)
	}
}

func (m *QueueStatus) decode(d *decoder) {
	m.Status = d.getU32()
	m.F1 = d.getI32()
	m.Stats = make([]QueueStats, d.count(168))
	for i1 := range m.Stats {
		m.Stats[i1].decode(d)
	}
	m.Ticket.decode(d)
	m.Tickets1 = make([]MatchmakingTicket, d.count(256))
	for i1 := range m.Tickets1 {
		m.Tickets1[i1].decode(d)
	}
	m.Tickets2 = make([]MatchmakingTicket, d.count(256))
	for i1 := range m.Tickets2 {
		m.Tickets2[i1].decode(d)
	}
	m.Entries = make([]QueueEntry, d.count(435))
	for i1 := range m.Entries {
		m.Entries[i1].decode(d)
	}
}

